      &lt;LastModifiedBy&gt;9&lt;/LastModifiedBy&gt;
      &lt;ActionData&gt;{&quot;ActionList&quot;:[{&quot;Title&quot;:&quot;Run SQL Query&quot;,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Description&quot;:&quot;Search Salariati&quot;,&quot;Condition&quot;:&quot;[p_Marca] !=\&quot;\&quot;&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;SELECT Nume, CNP FROM app.Salariat WHERE Marca = @Marca\nAND CodSucursala=&#39;[GetOrSession:BranchV]&#39;\nand Anul=[GetOrSession:YearV]\nand Luna=[GetOrSession:MonthV];&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[p_Marca]&quot;,&quot;name&quot;:&quot;Marca&quot;}],&quot;OutputTokenName&quot;:&quot;DateIdent&quot;,&quot;ExtractColumns&quot;:&quot;&quot;,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false},&quot;$_uid&quot;:&quot;action17745139108853529&quot;,&quot;$_isOpen&quot;:false,&quot;$_isLoaded&quot;:true,&quot;$_isFocus&quot;:true,&quot;EventName&quot;:&quot;click&quot;,&quot;Definition&quot;:{&quot;Id&quot;:&quot;RunSql&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Run SQL Query&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Executes the specified SQL query, optionally storing the output for use in other actions.&quot;},&quot;TypeStr&quot;:&quot;DnnSharp.Common.Actions.Data.ExecuteSql, DnnSharp.Common.Actions&quot;,&quot;Final&quot;:false,&quot;IsClientAction&quot;:false,&quot;Groups&quot;:[],&quot;Parameters&quot;:[{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;DbConnector&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Database&quot;},&quot;HelpText&quot;:{},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;ActionCredentials&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{&quot;Selection&quot;:&quot;Single&quot;,&quot;Type&quot;:&quot;Database&quot;},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[{&quot;TypeStr&quot;:&quot;DnnSharp.Common2.Services.PlantAnApp.ConfigConditions.IsPlantAnApp,DnnSharp.Common2&quot;,&quot;Settings&quot;:{}}],&quot;$_cleanHashKey&quot;:&quot;17744349084271493&quot;},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;ConnectionString&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Override Connection String&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;By default, the SQL will run against the built-in database or the selected Connection. Use this field to override the connection string. Also supports the name of a connection string from the web.config. It will respect the Provider (ODBC, SqlClient, etc.). Can contain Tokens. Read more about &amp;lt;a href=\&quot;http://www.connectionstrings.com/\&quot; target=\&quot;_blank\&quot;&amp;gt;supported formats&amp;lt;/a&amp;gt;.&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Text&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;QueryTimeout&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Query Timeout&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Set a time in seconds after which a query will time out. The default is set 10 minutes or 600 seconds also this parameter can&#39;t be negative or under 10 seconds. Can contain Tokens. &quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Text&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;SqlQuery&quot;,&quot;Title&quot;:{&quot;default&quo