      &lt;ActionData&gt;{&quot;ActionList&quot;:[{&quot;Title&quot;:&quot;Run SQL Query&quot;,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Description&quot;:&quot;Interval CO disponibil (in CO si CM)&quot;,&quot;Condition&quot;:&quot;&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:true,&quot;Entry&quot;:&quot;&quot;},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;SELECT \n    IIF(\n        EXISTS (\n            SELECT 1\n            FROM app.ConcediudeOdihna co\n            WHERE co.Marca = @marca\n              AND co.DatadeInceput &amp;lt; @end\n              AND co.DatadeSfarsit &amp;gt; @start\n        )\n        OR EXISTS (\n            SELECT 1\n            FROM app.ConcediuMedical cm\n            WHERE cm.Marca = @marca\n              AND cm.DatadeInceput &amp;lt; @end\n              AND cm.DatadeSfarsit &amp;gt; @start\n        ),\n        0, -- suprapunere cu CO sau CM\n        1  -- liber\n    ) AS disponibil;\n&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[p_DatadeInceput]&quot;,&quot;name&quot;:&quot;start&quot;},{&quot;value&quot;:&quot;[p_DatadeSfarsit]&quot;,&quot;name&quot;:&quot;end&quot;},{&quot;value&quot;:&quot;[GET:p_Marca]&quot;,&quot;name&quot;:&quot;marca&quot;}],&quot;OutputTokenName&quot;:&quot;interval&quot;,&quot;ExtractColumns&quot;:&quot;&quot;,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false},&quot;$_uid&quot;:&quot;action17744332349929260&quot;,&quot;$_isOpen&quot;:true,&quot;$_isLoaded&quot;:true,&quot;$_isFocus&quot;:true,&quot;EventName&quot;:&quot;click&quot;}],&quot;OnError&quot;:[{&quot;Title&quot;:&quot;Display Toast Message And Stop Execution&quot;,&quot;ActionType&quot;:&quot;ShowToast&quot;,&quot;Description&quot;:&quot;Verificare perioada CO disponibila&quot;,&quot;Condition&quot;:&quot;[interval:disponibil] != &#39;&#39; &amp;amp;&amp;amp; [interval