ors&quot;:false},&quot;$_uid&quot;:&quot;action17744341347029195&quot;,&quot;$_isOpen&quot;:true,&quot;$_isLoaded&quot;:true,&quot;$_isFocus&quot;:true,&quot;EventName&quot;:&quot;click&quot;},{&quot;Title&quot;:&quot;Display Toast Message And Stop Execution&quot;,&quot;ActionType&quot;:&quot;ShowToast&quot;,&quot;Description&quot;:&quot;Verificare Zile CO ramase pentru AnReferinta&quot;,&quot;Condition&quot;:&quot;[Token:ZileCORamase] &amp;lt; [ZileCODrept]&quot;,&quot;Parameters&quot;:{&quot;Heading&quot;:&quot;Atentionare!&quot;,&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;Ati introdus mai multe zile de CO dec&#226;t cele disponibile!&amp;lt;/p&amp;gt;&quot;,&quot;Icon&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;warning&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;BgColor&quot;:&quot;#2d88a6&quot;,&quot;Transition&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;slide&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;AllowToastClose&quot;:true,&quot;CallBackJsCode&quot;:&quot;&quot;,&quot;HideTime&quot;:&quot;10000&quot;,&quot;Stack&quot;:&quot;1&quot;,&quot;ToastPosition&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;bottom-center&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;TextAlignment&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;left&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;ShowLoader&quot;:true,&quot;LoaderColor&quot;:&quot;#FFFF00&quot;},&quot;$_uid&quot;:&quot;action17744341347029975&quot;,&quot;$_isOpen&quot;:true,&quot;$_isLoaded&quot;:true,&quot;$_isFocus&quot;:true,&quot;EventName&quot;:&quot;click&quot;}],&quot;OnError&quot;:[]}&lt;/ActionData&gt;
